const coverage=[['MSFT','Microsoft','Quality compounder','12–24M','8.6','Investor event · Sep 22','$447.67','+2.4%','9.4','6.2','Improving'],['ASML','ASML Holding','AI capex bottleneck','12–18M','8.2','Earnings · Oct 15','€823.10','−1.2%','9.2','5.8','Stable'],['V','Visa','Payments compounder','18–36M','7.9','Results · Oct 28','$336.24','+0.7%','9.0','6.7','Improving'],['NESN','Nestlé','Margin recovery','6–12M','7.1','Sales update · Oct 16','CHF 80.10','+0.3%','8.1','7.4','Turning']];
const ideas=document.querySelector('#ideas');if(ideas)ideas.innerHTML=coverage.map(a=>'<tr><td class="assetname"><b>'+a[0]+' · '+a[1]+'</b><small>Global equities</small></td><td>'+a[2]+'</td><td><span class="badge">'+a[3]+'</span></td><td class="conviction">'+a[4]+' / 10</td><td>'+a[5]+'</td></tr>').join('');
const rows=document.querySelector('#watchlistRows');if(rows)rows.innerHTML=coverage.map(a=>'<tr><td class="assetname"><b>'+a[0]+'</b><small>'+a[1]+'</small></td><td>'+a[6]+'</td><td class="'+(a[7].includes('−')?'red':'positive')+'">'+a[7]+'</td><td>'+a[8]+' / 10</td><td>'+a[9]+' / 10</td><td>'+a[10]+'</td><td><span class="badge">'+a[4]+' / 10</span></td><td>'+a[5]+'</td></tr>').join('');
const labels={dashboard:'COMMAND CENTER',research:'RESEARCH COCKPIT',watchlist:'ACTIVE WATCHLIST',calendar:'EVENT CALENDAR',briefing:'DAILY BRIEFING',reports:'AI RESEARCH REPORTS',chat:'ANALYST COPILOT'};function go(view){document.querySelectorAll('.view').forEach(v=>v.classList.remove('visible'));document.getElementById(view).classList.add('visible');document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===view));document.querySelector('#crumb').textContent=labels[view];window.scrollTo({top:0,behavior:'smooth'})}document.querySelectorAll('[data-view]').forEach(el=>el.addEventListener('click',()=>go(el.dataset.view)));
document.querySelectorAll('.suggestions button').forEach(b=>b.onclick=()=>{document.querySelector('#chatInput').value=b.textContent;document.querySelector('#chatForm').requestSubmit()});document.querySelector('#chatForm')?.addEventListener('submit',e=>{e.preventDefault();const input=document.querySelector('#chatInput'),q=input.value.trim();if(!q)return;const box=document.querySelector('#messages');box.insertAdjacentHTML('beforeend','<div class="message" style="margin:16px 0 0 auto;background:#203d34"><small>YOU · NOW</small><p>'+q.replace(/</g,'&lt;')+'</p></div>');input.value='';setTimeout(()=>box.insertAdjacentHTML('beforeend','<div class="message bot" style="margin-top:16px"><small>COPILOT · NOW</small><p>Demo response: I would retrieve the relevant filings, earnings transcripts, estimates and validated news, then separate facts, assumptions, catalysts and risks with links to each source. A production response requires connected data providers and an AI backend.</p></div>'),350)});
